  if p.startswith('skills/') and p.endswith('/SKILL.md') and p.count('/')==2: ok=True
  if ok and p.endswith('.md'): r.append(p)
 return sorted(set(r))
def content(commit,p):
 try: return subprocess.check_output(['git','show',f'{commit}:{p}'],text=True,stderr=subprocess.DEVNULL)
 except subprocess.CalledProcessError: return None
def wc_words(s): return len(re.findall(r'\S+',s))
def count(commit):
 totalw=totall=0; rows={}
