print('TOP_POS_WORD')
for dw,dl,p,bw0,hw0,bl0,hl0 in sorted(rows,reverse=True)[:15]: print(f'{dw:+6}w {dl:+5}l {p} ({bw0}->{hw0}w {bl0}->{hl0}l)')
print('TOP_NEG_WORD')
for dw,dl,p,bw0,hw0,bl0,hl0 in sorted(rows)[:15]: print(f'{dw:+6}w {dl:+5}l {p} ({bw0}->{hw0}w {bl0}->{hl0}l)')
